#!/bin/sh
# Generated by Blossom. This fixed template is rendered by the control plane;
# placeholders are substituted with validated values, never with free text.
# The installer takes no arguments. Do not add `set -x`: it would print secrets.
set -eu

ORIGIN=@@ORIGIN@@
SERVER_ID=@@SERVER_ID@@
GRANT_ID=@@GRANT_ID@@
MODE=@@MODE@@
RELEASE_VERSION=@@RELEASE_VERSION@@
AGENT_VERSION=@@AGENT_VERSION@@
SING_BOX_VERSION=@@SING_BOX_VERSION@@
AGENT_URL=
AGENT_SHA256=
SING_BOX_URL=
SING_BOX_SHA256=
@@ENROLLMENT_GRANT_LINE@@

SERVICE=blossom-agent
SERVICE_USER=blossom-agent
SERVICE_GROUP=blossom-agent
INSTALL_DIR=/usr/local/lib/blossom-agent
CONFIG_DIR=/etc/blossom-agent
STATE_DIR=/var/lib/blossom-agent
UNIT_FILE=/etc/systemd/system/blossom-agent.service
AGENT_FILE=$INSTALL_DIR/server-agent
SING_BOX_FILE=$INSTALL_DIR/sing-box
CREDENTIALS_FILE=$CONFIG_DIR/credentials.json
METADATA_FILE=$CONFIG_DIR/installation.json

PATH=/usr/sbin:/usr/bin:/sbin:/bin
export PATH
umask 077

staging=
commit_started=0
rollback_done=0
had_install=0
had_agent=0
had_singbox=0
had_unit=0
had_credentials=0
had_metadata=0
reset_state=0
state_archived=

log() {
  printf '[blossom-install] %s\n' "$*" >&2
}

fail() {
  log "error: $*"
  exit 1
}

backup_file() {
  src=$1
  dest=$2
  if [ -e "$src" ]; then
    cp -p "$src" "$dest"
    return 0
  fi
  return 1
}

restore_file() {
  existed=$1
  backup=$2
  target=$3
  if [ "$existed" -eq 1 ] && [ -f "$backup" ]; then
    cp -p "$backup" "$target.rollback" && mv -f "$target.rollback" "$target"
  else
    rm -f "$target"
  fi
}

rollback() {
  [ "$rollback_done" -eq 0 ] || return 0
  rollback_done=1
  log "installation failed; restoring the previous service"
  set +e
  systemctl stop "$SERVICE" >/dev/null 2>&1
  if [ -n "$state_archived" ] && [ -e "$state_archived" ]; then
    rm -rf "$STATE_DIR"
    mv "$state_archived" "$STATE_DIR"
  fi
  restore_file "$had_agent" "$staging/agent.backup" "$AGENT_FILE"
  restore_file "$had_singbox" "$staging/singbox.backup" "$SING_BOX_FILE"
  restore_file "$had_unit" "$staging/unit.backup" "$UNIT_FILE"
  restore_file "$had_credentials" "$staging/credentials.backup" "$CREDENTIALS_FILE"
  restore_file "$had_metadata" "$staging/metadata.backup" "$METADATA_FILE"
  systemctl daemon-reload >/dev/null 2>&1
  if [ "$had_install" -eq 1 ]; then
    systemctl enable "$SERVICE" >/dev/null 2>&1
    systemctl start "$SERVICE" >/dev/null 2>&1
    if systemctl is-active --quiet "$SERVICE"; then
      log "previous service restored"
    else
      log "previous service could not be restarted; inspect systemctl status $SERVICE"
    fi
  else
    systemctl disable "$SERVICE" >/dev/null 2>&1
    log "new service removed; no previous installation existed"
  fi
  set -e
}

cleanup() {
  status=$?
  trap - EXIT HUP INT TERM
  if [ "$status" -ne 0 ] && [ "$commit_started" -eq 1 ]; then
    rollback
  fi
  if [ -n "$staging" ] && [ -d "$staging" ]; then
    rm -rf "$staging"
  fi
  exit "$status"
}

trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM HUP

if [ "$#" -ne 0 ]; then
  fail "this installer takes no arguments and no credentials on the command line"
fi

for tool in chmod chown cp curl cut date find grep id install mkdir mktemp mv rm sed sha256sum sleep stty systemctl tar uname useradd wc; do
  command -v "$tool" >/dev/null 2>&1 || fail "required tool missing: $tool"
done

if [ -f "$0" ]; then
  chmod 0600 "$0" 2>/dev/null || true
fi
[ "$(id -u)" -eq 0 ] || fail "run as root (for example: sudo sh ./blossom-agent-install.sh)"
[ "$(uname -s)" = Linux ] || fail "this installer supports Linux only"

case "$(uname -m)" in
  x86_64|amd64)
    architecture=amd64
    AGENT_URL=@@AGENT_URL_AMD64@@
    AGENT_SHA256=@@AGENT_SHA256_AMD64@@
    SING_BOX_URL=@@SING_BOX_URL_AMD64@@
    SING_BOX_SHA256=@@SING_BOX_SHA256_AMD64@@
    ;;
  aarch64|arm64)
    architecture=arm64
    AGENT_URL=@@AGENT_URL_ARM64@@
    AGENT_SHA256=@@AGENT_SHA256_ARM64@@
    SING_BOX_URL=@@SING_BOX_URL_ARM64@@
    SING_BOX_SHA256=@@SING_BOX_SHA256_ARM64@@
    ;;
  *) fail "unsupported architecture: $(uname -m)" ;;
esac

systemctl --version >/dev/null 2>&1 || fail "systemd is required"

case "$ORIGIN" in
  https://*) ;;
  *) fail "the control-plane origin must use https://" ;;
esac
case "$AGENT_URL" in
  https://*) ;;
  *) fail "the server-agent download URL must use https://" ;;
esac
case "$SING_BOX_URL" in
  https://*) ;;
  *) fail "the sing-box download URL must use https://" ;;
esac
case "$AGENT_SHA256" in
  *[!0-9a-f]*|"") fail "agent SHA-256 is invalid" ;;
esac
case "$SING_BOX_SHA256" in
  *[!0-9a-f]*|"") fail "sing-box SHA-256 is invalid" ;;
esac
[ "${#AGENT_SHA256}" -eq 64 ] || fail "agent SHA-256 is invalid"
[ "${#SING_BOX_SHA256}" -eq 64 ] || fail "sing-box SHA-256 is invalid"

case "$MODE" in
  enroll|replace) ;;
  *) fail "invalid enrollment mode" ;;
esac

case "${BLOSSOM_INSTALL_CONFIRM:-}" in
  ""|replace) ;;
  *) fail "BLOSSOM_INSTALL_CONFIRM must be empty or 'replace'" ;;
esac

health_seconds=${BLOSSOM_INSTALL_HEALTH_SECONDS:-5}
case "$health_seconds" in
  *[!0-9]*|"") fail "BLOSSOM_INSTALL_HEALTH_SECONDS must be an integer" ;;
esac
[ "$health_seconds" -le 60 ] || fail "BLOSSOM_INSTALL_HEALTH_SECONDS must be at most 60"

existing_server=
existing_origin=
existing_release=
existing_grant=
if [ -f "$METADATA_FILE" ]; then
  existing_server=$(sed -n 's/^server_id=//p' "$METADATA_FILE")
  existing_origin=$(sed -n 's/^origin=//p' "$METADATA_FILE")
  existing_release=$(sed -n 's/^release=//p' "$METADATA_FILE")
  existing_grant=$(sed -n 's/^grant_id=//p' "$METADATA_FILE")
fi

if [ -e "$UNIT_FILE" ] || [ -e "$AGENT_FILE" ] || [ -e "$CREDENTIALS_FILE" ] || [ -e "$METADATA_FILE" ]; then
  had_install=1
  if [ "$existing_server" != "$SERVER_ID" ] || [ "$existing_origin" != "$ORIGIN" ] || [ -z "$existing_server" ] || [ -z "$existing_origin" ]; then
    if [ "${BLOSSOM_INSTALL_CONFIRM:-}" != replace ]; then
      fail "a different or unidentifiable Blossom installation exists; set BLOSSOM_INSTALL_CONFIRM=replace to replace it"
    fi
    reset_state=1
  fi
fi

already_installed() {
  log "this grant is already installed for $SERVER_ID at release $RELEASE_VERSION"
  log "the control-plane configuration acknowledgment is reported separately from this local service state"
  exit 0
}

if [ "$had_install" -eq 1 ] && [ "$existing_grant" = "$GRANT_ID" ] && [ "$existing_release" = "$RELEASE_VERSION" ] && [ -x "$AGENT_FILE" ]; then
  if systemctl is-active --quiet "$SERVICE"; then
    already_installed
  fi
  log "the grant is already installed but the service is inactive; restarting the existing service"
  systemctl enable "$SERVICE" >/dev/null
  systemctl start "$SERVICE"
  [ "$health_seconds" -eq 0 ] || sleep "$health_seconds"
  systemctl is-active --quiet "$SERVICE" || fail "existing service did not become active"
  already_installed
fi

if ! id -u "$SERVICE_USER" >/dev/null 2>&1; then
  useradd --system --user-group --home-dir "$STATE_DIR" --shell /usr/sbin/nologin "$SERVICE_USER" ||
    fail "cannot create the $SERVICE_USER service account"
fi

install -d -m 0755 "$INSTALL_DIR"
staging=$(mktemp -d "$INSTALL_DIR/.install.XXXXXX")

download() {
  curl --fail --show-error --silent --location \
    --proto '=https' --proto-redir '=https' --tlsv1.2 \
    --retry 2 --retry-delay 2 --connect-timeout 15 --max-time 300 \
    --output "$2" "$1"
}

verify_sha256() {
  expected=$1
  file=$2
  actual=$(sha256sum "$file" | cut -d' ' -f1)
  [ "$actual" = "$expected" ] || fail "SHA-256 mismatch for $file"
}

log "downloading server-agent $AGENT_VERSION for $architecture"
download "$AGENT_URL" "$staging/server-agent"
verify_sha256 "$AGENT_SHA256" "$staging/server-agent"
chmod 0755 "$staging/server-agent"

log "downloading sing-box $SING_BOX_VERSION for $architecture"
download "$SING_BOX_URL" "$staging/sing-box.tar.gz"
verify_sha256 "$SING_BOX_SHA256" "$staging/sing-box.tar.gz"

tar -tzf "$staging/sing-box.tar.gz" >"$staging/sing-box-members"
if grep -Eq '(^/|(^|/)\.\.(/|$))' "$staging/sing-box-members"; then
  fail "sing-box archive contains an unsafe path"
fi
mkdir -m 0700 "$staging/sing-box"
tar -xzf "$staging/sing-box.tar.gz" -C "$staging/sing-box"
sing_box_candidates=$(find "$staging/sing-box" -type f -name sing-box | wc -l)
[ "$sing_box_candidates" -eq 1 ] || fail "sing-box archive must contain exactly one sing-box binary"
staged_sing_box=$(find "$staging/sing-box" -type f -name sing-box)
chmod 0755 "$staged_sing_box"

agent_version_output=$("$staging/server-agent" --version 2>&1) ||
  fail "the downloaded server-agent does not run"
case "$agent_version_output" in
  *"$AGENT_VERSION"*) ;;
  *) fail "downloaded server-agent does not report version $AGENT_VERSION" ;;
esac
sing_box_version_output=$("$staged_sing_box" version 2>&1) ||
  fail "the downloaded sing-box does not run"
case "$sing_box_version_output" in
  *"$SING_BOX_VERSION"*) ;;
  *) fail "downloaded sing-box does not report version $SING_BOX_VERSION" ;;
esac

if [ -z "$enrollment_grant" ]; then
  if [ "${BLOSSOM_GRANT_STDIN:-0}" = 1 ]; then
    IFS= read -r enrollment_grant || fail "no enrollment grant was provided on stdin"
  elif [ -t 0 ]; then
    printf 'Enrollment grant: ' >/dev/tty
    old_stty=$(stty -g </dev/tty)
    stty -echo </dev/tty
    if ! IFS= read -r enrollment_grant </dev/tty; then
      stty "$old_stty" </dev/tty
      fail "no enrollment grant was provided"
    fi
    stty "$old_stty" </dev/tty
    printf '\n' >/dev/tty
  elif [ -r /dev/tty ]; then
    printf 'Enrollment grant: ' >/dev/tty
    old_stty=$(stty -g </dev/tty)
    stty -echo </dev/tty
    if ! IFS= read -r enrollment_grant </dev/tty; then
      stty "$old_stty" </dev/tty
      fail "no enrollment grant was provided"
    fi
    stty "$old_stty" </dev/tty
    printf '\n' >/dev/tty
  else
    fail "provide the one-time grant on stdin with BLOSSOM_GRANT_STDIN=1"
  fi
fi

case "$enrollment_grant" in
  egr_*) ;;
  *) fail "invalid enrollment grant" ;;
esac
case "$enrollment_grant" in
  *[!A-Za-z0-9_-]*|"") fail "invalid enrollment grant" ;;
esac
[ "${#enrollment_grant}" -eq 47 ] || fail "invalid enrollment grant"

printf '%s\n' "$enrollment_grant" >"$staging/enrollment-grant"
chmod 0600 "$staging/enrollment-grant"

log "redeeming the one-time grant as the Rust enrollment client"
if ! "$staging/server-agent" enroll \
  --url "$ORIGIN/api" \
  --grant-file "$staging/enrollment-grant" \
  --credentials-file "$staging/credentials.json"; then
  fail "enrollment failed; ask an administrator to inspect or revoke the grant before issuing a new one"
fi
rm -f "$staging/enrollment-grant"
enrollment_grant=

[ -s "$staging/credentials.json" ] || fail "the enrollment client did not write credentials"
[ "$(wc -c <"$staging/credentials.json")" -le 16384 ] || fail "the credential file is unexpectedly large"
grep -q '"clientId"' "$staging/credentials.json" || fail "the credential file has no clientId"
grep -q '"clientSecret"' "$staging/credentials.json" || fail "the credential file has no clientSecret"

if backup_file "$AGENT_FILE" "$staging/agent.backup"; then had_agent=1; fi
if backup_file "$SING_BOX_FILE" "$staging/singbox.backup"; then had_singbox=1; fi
if backup_file "$UNIT_FILE" "$staging/unit.backup"; then had_unit=1; fi
if backup_file "$CREDENTIALS_FILE" "$staging/credentials.backup"; then had_credentials=1; fi
if backup_file "$METADATA_FILE" "$staging/metadata.backup"; then had_metadata=1; fi

cat >"$staging/blossom-agent.service" <<EOF_UNIT
[Unit]
Description=Blossom server agent
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=$SERVICE_USER
Group=$SERVICE_GROUP
WorkingDirectory=$STATE_DIR
ExecStart=$AGENT_FILE --url $ORIGIN/api --credentials-file $CREDENTIALS_FILE --state-dir $STATE_DIR --sing-box-path $SING_BOX_FILE --download-dir $STATE_DIR/downloads --self-update=false@@PTY_FLAG@@
Restart=on-failure
RestartSec=5
UMask=0077
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=true
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX
RestrictSUIDSGID=true
LockPersonality=true
MemoryDenyWriteExecute=true
CapabilityBoundingSet=CAP_NET_BIND_SERVICE
AmbientCapabilities=CAP_NET_BIND_SERVICE
ReadWritePaths=$STATE_DIR

[Install]
WantedBy=multi-user.target
EOF_UNIT

cat >"$staging/installation.json" <<EOF_METADATA
server_id=$SERVER_ID
origin=$ORIGIN
release=$RELEASE_VERSION
grant_id=$GRANT_ID
mode=$MODE
installed_at=$(date -u +%Y-%m-%dT%H:%M:%SZ)
EOF_METADATA

commit_started=1
if [ "$had_install" -eq 1 ]; then
  systemctl stop "$SERVICE" >/dev/null 2>&1 || true
fi

install -d -m 0700 "$CONFIG_DIR"
chown "$SERVICE_USER:$SERVICE_GROUP" "$CONFIG_DIR"
chmod 0700 "$CONFIG_DIR"

if [ "$reset_state" -eq 1 ] && [ -d "$STATE_DIR" ]; then
  state_archived="$STATE_DIR.previous-$(date -u +%Y%m%dT%H%M%SZ)"
  mv "$STATE_DIR" "$state_archived"
fi
install -d -m 0700 "$STATE_DIR"
chown "$SERVICE_USER:$SERVICE_GROUP" "$STATE_DIR"
chmod 0700 "$STATE_DIR"

install -m 0755 "$staging/server-agent" "$INSTALL_DIR/.server-agent.new"
mv -f "$INSTALL_DIR/.server-agent.new" "$AGENT_FILE"
install -m 0755 "$staged_sing_box" "$INSTALL_DIR/.sing-box.new"
mv -f "$INSTALL_DIR/.sing-box.new" "$SING_BOX_FILE"
install -o "$SERVICE_USER" -g "$SERVICE_GROUP" -m 0600 "$staging/credentials.json" "$CONFIG_DIR/.credentials.new"
mv -f "$CONFIG_DIR/.credentials.new" "$CREDENTIALS_FILE"
install -m 0644 "$staging/blossom-agent.service" "$UNIT_FILE.new"
mv -f "$UNIT_FILE.new" "$UNIT_FILE"
install -m 0600 "$staging/installation.json" "$METADATA_FILE"

systemctl daemon-reload
systemctl enable "$SERVICE" >/dev/null
if [ "$had_install" -eq 1 ]; then
  systemctl restart "$SERVICE"
else
  systemctl start "$SERVICE"
fi
[ "$health_seconds" -eq 0 ] || sleep "$health_seconds"
systemctl is-active --quiet "$SERVICE" || fail "the service did not remain active"

if [ "$had_agent" -eq 1 ]; then
  cp -p "$staging/agent.backup" "$INSTALL_DIR/server-agent.previous"
fi
if [ "$had_singbox" -eq 1 ]; then
  cp -p "$staging/singbox.backup" "$INSTALL_DIR/sing-box.previous"
fi
if [ "$had_unit" -eq 1 ]; then
  cp -p "$staging/unit.backup" "$INSTALL_DIR/blossom-agent.service.previous"
fi

log "installed server-agent $AGENT_VERSION and sing-box $SING_BOX_VERSION"
log "systemd service state is active; the control-plane configuration acknowledgment is separate"
systemctl status "$SERVICE" --no-pager >&2 || true
if [ -n "$state_archived" ]; then
  log "previous server state was archived at $state_archived"
fi
cat >&2 <<'EOF_UNINSTALL'
To uninstall this host installation:
  systemctl disable --now blossom-agent
  rm -f /etc/systemd/system/blossom-agent.service
  systemctl daemon-reload
  rm -rf /usr/local/lib/blossom-agent /etc/blossom-agent /var/lib/blossom-agent
  userdel blossom-agent
Revoke the control-plane identity first if this host will not be reused.
EOF_UNINSTALL

exit 0
